import{_ as o,C as n,o as c,c as i,j as a,a as e,E as t,a2 as g}from"./chunks/framework.CNNkhf_4.js";const b=JSON.parse('{"title":"condition","description":"","frontmatter":{},"headers":[],"relativePath":"language/elements/trigger/condition.md","filePath":"language/elements/trigger/condition.md"}'),m={name:"language/elements/trigger/condition.md"};function r(d,s,x,u,y,_){const l=n("AvailabilityCard"),p=n("EnumVersionTable");return c(),i("div",null,[s[0]||(s[0]=a("h1",{id:"condition",tabindex:"-1"},[e("condition "),a("a",{class:"header-anchor",href:"#condition","aria-label":'Permalink to "condition"'},"​")],-1)),t(l,{reach:"yes",halo4:"yes",h2a:"yes"}),s[1]||(s[1]=a("p",null,[a("strong",null,"Conditions"),e(" are predicates inside triggers that control when actions run. When a condition evaluates to false, the trigger "),a("strong",null,"halts"),e(" — subsequent conditions and actions in that trigger are skipped for the current evaluation.")],-1)),s[2]||(s[2]=a("p",null,[e("Condition names match "),a("code",null,"e_condition_type"),e(" in "),a("a",{href:"https://github.com/Blam-Network/blf/blob/main/blf-ts/src/blam/haloreach_mcc/v_untracked_25_08_16_1352/game/megalogamengine/megalogamengine_conditions.ts",target:"_blank",rel:"noreferrer"},"@blamnetwork/blf"),e(" ("),a("code",null,"none"),e(" is a wire sentinel and is not written in source).")],-1)),t(p,{enum:"condition-types"}),s[3]||(s[3]=g(`<h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">condition [not] &lt;name&gt; [arg1] [arg2] ... [or]</span></span></code></pre></div><ul><li><strong><code>not</code></strong> — optional prefix that negates the result</li><li><strong><code>name</code></strong> — the condition type (e.g. <code>if</code>, <code>player_died</code>, <code>timer_expired</code>)</li><li><strong>args</strong> — operands specific to the condition type</li><li><strong><code>or</code></strong> — optional suffix that joins this condition with the next using logical OR</li></ul><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> if score_to_win_round != 0</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-text">==</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">enemy</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">not</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">heard_game_start</span><span class="megalo-text"> </span><span class="megalo-text">==</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">timer_expired</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">game_start_vo</span></span></code></pre></div><h2 id="comparison-conditions-if" tabindex="-1">Comparison conditions (<code>if</code>) <a class="header-anchor" href="#comparison-conditions-if" aria-label="Permalink to &quot;Comparison conditions (\`if\`)&quot;">​</a></h2><p>The <code>if</code> condition compares two values. It supports several operator spellings:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Alternatives</th></tr></thead><tbody><tr><td><code>equal_to</code></td><td><code>==</code></td></tr><tr><td><code>not equal_to</code></td><td><code>!=</code></td></tr><tr><td><code>less_than</code></td><td><code>&lt;</code></td></tr><tr><td><code>greater_than</code></td><td><code>&gt;</code></td></tr><tr><td><code>less_than_or_equal_to</code></td><td><code>&lt;=</code></td></tr><tr><td><code>greater_than_or_equal_to</code></td><td><code>&gt;=</code></td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> if hidden_gametype equal_to k_hidden_swat</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-text">!=</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">round_time_limit</span><span class="megalo-text"> </span><span class="megalo-text">&gt;</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">is_leader</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-keyword">true</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">shields</span><span class="megalo-text"> </span><span class="megalo-text">&gt;</span><span class="megalo-text"> </span><span class="megalo-number">100</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">not</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">score</span><span class="megalo-text"> </span><span class="megalo-text">==</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span></code></pre></div><p>Both sides of a comparison can be variables, constants, built-in globals, game options, or member variables.</p><h2 id="event-conditions" tabindex="-1">Event conditions <a class="header-anchor" href="#event-conditions" aria-label="Permalink to &quot;Event conditions&quot;">​</a></h2><p>Event conditions test game state rather than comparing values. The table above lists every condition type; common examples:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> player_died current_player enemy</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">timer_expired</span><span class="megalo-text"> </span><span class="megalo-text">round_timer</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">object_in_area</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">current_object</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">object_out_of_bounds</span><span class="megalo-text"> </span><span class="megalo-text">current_team</span><span class="megalo-text">.</span><span class="megalo-text">flag</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">team_is_active</span><span class="megalo-text"> </span><span class="megalo-text">current_team</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">object_is_type</span><span class="megalo-text"> </span><span class="megalo-text">current_object</span><span class="megalo-text"> </span><span class="megalo-string">&quot;area&quot;</span></span></code></pre></div><h3 id="player-died-killer-types" tabindex="-1">player_died killer types <a class="header-anchor" href="#player-died-killer-types" aria-label="Permalink to &quot;player_died killer types&quot;">​</a></h3><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> player_died current_player environment</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">suicide</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">enemy</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">betrayal</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">quit_game</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">any</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">not</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">enemy</span></span></code></pre></div><h2 id="combining-conditions" tabindex="-1">Combining conditions <a class="header-anchor" href="#combining-conditions" aria-label="Permalink to &quot;Combining conditions&quot;">​</a></h2><h3 id="and-implicit" tabindex="-1">AND (implicit) <a class="header-anchor" href="#and-implicit" aria-label="Permalink to &quot;AND (implicit)&quot;">​</a></h3><p>Separate condition lines act as a logical <strong>AND</strong>. All must be true for subsequent actions to run:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-keyword">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-condition">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">enemy</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-condition">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">is_leader</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-keyword">true</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-action">set_score</span><span class="megalo-text"> </span><span class="megalo-text">add</span><span class="megalo-text"> </span><span class="megalo-text">leader_kill_bonus</span><span class="megalo-text"> </span><span class="megalo-keyword">player</span><span class="megalo-text"> </span><span class="megalo-text">killing_player</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h3 id="or" tabindex="-1">OR <a class="header-anchor" href="#or" aria-label="Permalink to &quot;OR&quot;">​</a></h3><p>Append <code>or</code> to a condition line to join it with the next condition using logical <strong>OR</strong>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-keyword">general</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-condition">if</span><span class="megalo-text"> </span><span class="megalo-text">hidden_gametype</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">k_hidden_covy</span><span class="megalo-text"> </span><span class="megalo-keyword">or</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-condition">if</span><span class="megalo-text"> </span><span class="megalo-text">hidden_gametype</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">k_hidden_swat</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-action">for_each</span><span class="megalo-text"> </span><span class="megalo-text">health_packs</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-action">delete_object</span><span class="megalo-text"> </span><span class="megalo-text">current_object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Multiple <code>or</code>-joined conditions can span several lines:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> if current_player.team equal_to attackers or</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">team</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">fourth_party</span><span class="megalo-text"> </span><span class="megalo-keyword">or</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">team</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">third_party</span></span></code></pre></div><p>If the combined OR group evaluates to false, the trigger halts.</p><h3 id="not" tabindex="-1">NOT <a class="header-anchor" href="#not" aria-label="Permalink to &quot;NOT&quot;">​</a></h3><p>Prefix a condition with <code>not</code> to invert its result:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> not if current_player.heard_game_start == 0</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">not</span><span class="megalo-text"> </span><span class="megalo-text">player_died</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text"> </span><span class="megalo-text">enemy</span></span>
<span class="line"><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">not</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">one_flag</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">none</span></span></code></pre></div><h2 id="conditions-inside-for-each" tabindex="-1">Conditions inside for_each <a class="header-anchor" href="#conditions-inside-for-each" aria-label="Permalink to &quot;Conditions inside for_each&quot;">​</a></h2><p>Inside an <code>action for_each</code> sub-trigger, a false condition <strong>skips the current iteration</strong> rather than halting the entire trigger. This is equivalent to a <code>continue</code> statement:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">action</span><span class="megalo-text"> for_each player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">team</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">attackers</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-text">set</span><span class="megalo-text"> </span><span class="megalo-text">current_player</span><span class="megalo-text">.</span><span class="megalo-text">fireteam</span><span class="megalo-text"> </span><span class="megalo-text">set_to</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Only players on the attacking team have their fireteam set; other players are skipped.</p><h2 id="condition-placement" tabindex="-1">Condition placement <a class="header-anchor" href="#condition-placement" aria-label="Permalink to &quot;Condition placement&quot;">​</a></h2><p>Conditions can appear anywhere in a trigger — before actions, between actions, or after actions. Actions that appear before a failing condition have already executed:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-keyword">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">; this action always runs</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-action">set_pickup_filter</span><span class="megalo-text"> </span><span class="megalo-text">current_team</span><span class="megalo-text">.</span><span class="megalo-text">flag</span><span class="megalo-text"> </span><span class="megalo-text">enemies</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary</span><span class="megalo-text"> </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-text">carrier</span><span class="megalo-text"> </span><span class="megalo-text">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-action">get_player_holding_object</span><span class="megalo-text"> </span><span class="megalo-text">current_team</span><span class="megalo-text">.</span><span class="megalo-text">flag</span><span class="megalo-text"> </span><span class="megalo-text">carrier</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">; this condition gates what follows</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition</span><span class="megalo-text"> </span><span class="megalo-condition">not</span><span class="megalo-text"> </span><span class="megalo-text">if</span><span class="megalo-text"> </span><span class="megalo-text">carrier</span><span class="megalo-text"> </span><span class="megalo-text">equal_to</span><span class="megalo-text"> </span><span class="megalo-text">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action</span><span class="megalo-text"> </span><span class="megalo-action">apply_player_traits</span><span class="megalo-text"> </span><span class="megalo-text">carrier</span><span class="megalo-text"> </span><span class="megalo-text">flag_carrier_traits</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/./docs/language/elements/trigger">trigger</a> — trigger execution model and halt-on-false</li><li><a href="/./docs/language/elements/trigger/action">action</a> — actions that follow conditions</li><li><a href="/./docs/language/variable-model">Variable model</a> — operands in comparisons</li><li><a href="/./docs/language/references">References</a> — player, team, object operands</li></ul>`,36))])}const k=o(m,[["render",r]]);export{b as __pageData,k as default};
